export const addSubIdsToUrl = (affiliateLink: string, subIds: Record<string, string>) => {
	try {
		const url = new URL(affiliateLink);

		Object.keys(subIds).forEach((key) => {
			if (subIds[key]) {
				url.searchParams.set(`subid${key}`, subIds[key]);
			} else {
				url.searchParams.delete(`subid${key}`);
			}
		});

		return url.toString();
	} catch (_) {
		return '';
	}
};
